"""Purpose-led resource controls; source coordinates stay in a separate static asset."""
import json
from pathlib import Path
from html import escape as e
text=(Path(__file__).parent/'assets/map-resources.js').read_text()
CATALOG=json.loads(text.removeprefix('window.CODEX_MAP_RESOURCES=').strip().removesuffix(';'))
def panel(lang,base):
 t=lambda a,b:b if lang=='ko' else a
 r=base+('ko/' if lang=='ko' else '')
 options=f'<option value="gather_all">{t("All gathering materials","전체 채집 재료")}</option>'
 for cat,label in CATALOG['categories'].items():
  options+=f'<optgroup label="{e(label[lang])}">'+''.join(f'<option value="{key}">{e(v["name"][lang])}</option>' for key,v in CATALOG['materials'].items() if v['category']==cat)+'</optgroup>'
 return f'''<section class="resource-finder" aria-labelledby="resource-title"><span class="section-kicker">FARMING / COLLECTION</span><h2 id="resource-title">{t('What are you farming?','무엇을 파밍할까요?')}</h2><p>{t('Choose a material to find its gathering locations, its use and a nearby travel point.','필요한 재료를 고르면 채집 위치·사용처·가까운 이동 거점을 함께 볼 수 있습니다.')}</p><div class="map-goals"><button data-map-goal="gather" aria-pressed="true">{t('Gather materials','채집 재료 찾기')}</button><button data-map-goal="collect" aria-pressed="false">{t('Collect traces','내실·깃털 수집')}</button><button data-map-goal="dungeons" aria-pressed="false">{t('Dungeon rewards','던전 보상 찾기')}</button></div><div data-map-resource-panel><label class="resource-select">{t('Material needed','필요한 재료')}<select data-map-resource>{options}</select></label><article class="resource-brief"><h3 data-resource-name></h3><p data-resource-use></p><p class="small muted" data-resource-note></p><button class="text-link" data-resource-reset>{t('Reset this visit’s gathering checks','이번 동선의 채집 방문 표시 초기화')}</button></article></div><details class="resource-reference"><summary>{t('Need enhancement stones or dungeon materials instead?','강화석·제련석·데바니온 결정이 필요하다면?')}</summary><p>{t('These are obtained through extraction, monsters, dungeons or other activities. They are not all gathering nodes on the field map.','이 재료들은 추출·몬스터·던전 등 획득 방식이 다릅니다. 모두 필드에서 직접 채집하는 자원은 아닙니다.')}</p><div class="resource-reference-links"><a href="{r}routines/">{t('Enhancement stones → daily rewards','강화석 → 일일 던전·보상')}</a><a href="{r}guides/dungeon-rewards/">{t('Refining materials → dungeon rewards','제련 재료 → 던전 보상')}</a><a href="{r}endgame/">{t('Wisdom Stones & Daevanion → growth','지혜의 돌·데바니온 → 내실·사용처')}</a></div></details><details class="resource-reference"><summary>{t('Sources and regional names','출처와 서버별 재료 이름')}</summary><p>{t('Coordinates: TH.GL snapshot reviewed October 15, 2026. Uses: Global client guide cross-checked with older KR Inven articles. Localized names and recipes may differ by server. Pins are possible gathering locations, not live availability or guaranteed rare-grade drops.','좌표는 TH.GL의 2026-10-15 확인 자료입니다. 사용처는 글로벌 클라이언트 공략과 한국 인벤의 기존 공략을 대조했습니다. 서버별 이름·제작법은 다를 수 있습니다. 지도는 채집 가능 위치이며 실시간 출현·희귀 등급 획득을 보장하지 않습니다.')}</p><a href="https://www.inven.co.kr/board/aion2/6444/398" target="_blank" rel="noopener">Inven · {t('material uses (KR, Nov 2025)','재료 사용처 (한국·2025년 11월)')} ↗</a> · <a href="https://www.inven.co.kr/board/aion2/6444/534" target="_blank" rel="noopener">Inven · {t('crafting priorities','제작 재료 우선순위')} ↗</a> · <a href="https://metabot.gg/ko_KR/aion-2/guides/crafting-guide" target="_blank" rel="noopener">MetaBot · Global ↗</a></details></section>'''
